    inflate_state *state;
    long result;

    if (strm == NULL || strm->state == NULL) {
        return -1; // Specific error value for null stream or state
    }

    state = (inflate_state *)strm->state;

    result = (long)(state->back << 16);

    if (state->mode == COPY) {
        result += state->length;
    } else if (state->mode == MATCH) {
        result += (state->was - state->length);
    }

    return result;
}

